SZGame2D.onStart(function __szProjectRun() {
  const __szProjectRunContext = window.__SZProjectLifecycle.begin(() => SZGame2D.restart());
  // Ao iniciar
  SZGame2D.setupStage(800, 480, "#07162e");
  const nave = SZGame2D.createShip({ x: 400, y: 410, w: 54, h: 62, body: "#35e8ff", wings: "#2568ff" });
  const tiros = SZGame2D.createGroup();
  // Quando acontecer
  SZGame2D.onKey("Space", () => {
    SZGame2D.spawnBullet(tiros, { x: SZGame2D.centerX(nave), y: SZGame2D.spriteY(nave), radius: 5, color: "#9cff57", vx: 0, vy: -9 });
    SZGame2D.playFx("shoot");
  }, "nave-ref-23");
  // Enquanto estiver rodando
  // O jogo roda 60 passos por segundo: cada volta desenha um "quadro" do filme.
  SZGame2D.gameLoop(function update() {
    SZGame2D.clear();
    SZGame2D.drawStarfield(ctx, 1);
    SZGame2D.arrowsX(nave, 7);
    SZGame2D.clampToScreen(nave, ctx);
    SZGame2D.drawSprite(ctx, nave);
    SZGame2D.updateGroup(tiros);
    SZGame2D.pruneOffscreen(ctx, tiros, 40, (sprite) => {

    });
    SZGame2D.drawGroup(ctx, tiros);
  }, "nave-ref-11");
}, "__sz-project");
